package ma.enset.smartdevcollab.service;
import ma.enset.smartdevcollab.entity.*; import ma.enset.smartdevcollab.repository.*; import org.springframework.stereotype.Service; import java.util.*; import java.util.stream.*;
@Service public class AnalyticsService{ private final TaskRepository tasks; public AnalyticsService(TaskRepository tasks){this.tasks=tasks;} public Map<String,Object> project(Long id){ List<Task> list=tasks.findByProjectId(id); long total=list.size(); long done=list.stream().filter(t->t.getStatus()==TaskStatus.DONE).count(); Map<String,Long> byStatus=list.stream().collect(Collectors.groupingBy(t->t.getStatus().name(),Collectors.counting())); Map<String,Long> workload=list.stream().filter(t->t.getAssignedTo()!=null).collect(Collectors.groupingBy(t->t.getAssignedTo().getFullName(),Collectors.counting())); Map<String,Object> m=new LinkedHashMap<>(); m.put("total",total); m.put("done",done); m.put("progress", total==0?0:Math.round(done*100.0/total)); m.put("byStatus",byStatus); m.put("workload",workload); return m; } }
